 // - `\\.` makes the `.` character literal. When not escaped, it matches any character. 
 // - `{0,2}` means the regex matches the group's pattern (`\.\w+`) zero to two times. 
 // - The `?` makes the `!` character optional. 
 var string symbol = "\\w+(?:\\.\\w+){0,2}!?"

